def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    severe_need = (hp <= 2) or (no_water >= 2)
    moderate_need = (hp <= 4) or (no_water >= 1)

    if severe_need:
        target = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif moderate_need:
        target = max(DAILY_SALARY * 0.7, avg_prev + 2.0)
    else:
        if supply >= 22:
            target = DAILY_SALARY * 0.28
        elif supply >= 19:
            target = DAILY_SALARY * 0.42
        else:
            target = DAILY_SALARY * 0.58

        if highest_prev > 0:
            if highest_prev >= 100:
                target = min(target, DAILY_SALARY * 0.4)
            elif highest_prev >= 70:
                target = max(target, DAILY_SALARY * 0.52)
            else:
                target = max(target, highest_prev + 1.5)

    if rich_opp >= 1 and not severe_need:
        target *= 0.95
    if urgent_opp >= 2 and supply <= 18:
        target += 8.0

    if day >= 8 and budget > DAILY_SALARY * 6 and moderate_need:
        target += 6.0

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 2 and not severe_need:
        reserve_floor = DAILY_SALARY * 0.35

    affordable = max(0.0, budget - reserve_floor)
    bid = min(target, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, min(budget, DAILY_SALARY * 0.2)))

    if severe_need:
        bid = min(max(bid, DAILY_SALARY * 0.9), budget)
    elif moderate_need:
        bid = min(max(bid, DAILY_SALARY * 0.55), budget)
    else:
        bid = min(max(bid, 0.0), budget)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water.
    # The bid is a total bid for WATER_REQ units.
    if not alive_opponents:
        # Bid 1 unit per water requirement, total 13 units.
        return min(my_status['budget'], WATER_REQ * 1.0)

    # Collect yesterday's bids from alive opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents are bidding very high (e.g., > 85% of daily salary)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # Healthy HP, can afford to save a bit
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # Critical HP, must get water, bid aggressively
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        # Moderate bids from opponents, bid slightly above to win
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # Default bid if no previous bids (e.g., Day 1 or all opponents are new/dead)
    if my_status['hp'] <= 2: # Critical HP, bid high
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    # Healthy HP, bid moderately
    return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Analyze yesterday's traces from alive opponents
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Base bid calculated from supply scarcity
    scarcity = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0 to 1
    base_bid = DAILY_SALARY * (0.4 + 0.4 * scarcity)

    # Adjust based on yesterday's highest bid among alive opponents
    if prev_bids:
        max_prev_bid = max(prev_bids)
        # If someone was aggressive yesterday, expect continuation
        if max_prev_bid >= DAILY_SALARY * 0.85:
            # They might be desperate or dominant; bid high enough to secure water
            if hp <= 2:
                target = min(budget, max(base_bid, max_prev_bid + 2.0))
            else:
                target = min(budget, max(base_bid, max_prev_bid + 0.5))
        else:
            # Moderate yesterday, typical competition
            target = min(budget, max(base_bid * 1.1, max_prev_bid + 1.0))
    else:
        # No info from yesterday, use base
        target = min(budget, base_bid)

    # Ensure we never bid more than budget, and consider HP criticality
    if hp <= 2:
        target = max(target, min(budget, DAILY_SALARY * 0.9))
    elif hp <= 4:
        target = max(target, min(budget, DAILY_SALARY * 0.6))

    # Ensure reasonable upper bound
    target = min(target, budget, DAILY_SALARY * 1.2)
    return int(target)
